import React, { useState, useEffect } from 'react';
import { Brain, CheckCircle2, XCircle, Trophy, RotateCcw, ArrowLeft } from 'lucide-react';
import { articleRulesData, ArticleRule, ArticleWord } from '../../data/articleRules';
import { useAppContext } from '../../hooks/useAppContext';
import { languages } from '../../data/languages';

type GameMode = 'pattern-match' | 'article-predict' | 'fill-blank';
type Difficulty = 'easy' | 'medium' | 'hard';

interface GameQuestion {
  word: ArticleWord;
  correctArticle: 'der' | 'die' | 'das';
  rule: ArticleRule;
  options: ('der' | 'die' | 'das')[];
}

interface GameStats {
  correct: number;
  incorrect: number;
  streak: number;
  bestStreak: number;
  questionsByRule: Record<string, { correct: number; total: number }>;
}

export const ArticlePatternGame = () => {
  const { language } = useAppContext();
  const t = languages[language];

  const [gameMode, setGameMode] = useState<GameMode>('article-predict');
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentQuestion, setCurrentQuestion] = useState<GameQuestion | null>(null);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showResult, setShowResult] = useState(false);
  const [stats, setStats] = useState<GameStats>({
    correct: 0,
    incorrect: 0,
    streak: 0,
    bestStreak: 0,
    questionsByRule: {}
  });
  const [questionCount, setQuestionCount] = useState(0);
  const [usedRules, setUsedRules] = useState<Set<string>>(new Set());

  // Calculate total questions based on difficulty to cover all rules
  const getTotalQuestions = (): number => {
    const totalRules = articleRulesData.reduce((sum, cat) => sum + cat.rules.length, 0);

    if (difficulty === 'easy') {
      // Easy: 2-3 questions per rule for better practice
      return Math.min(totalRules * 2, 60);
    } else if (difficulty === 'medium') {
      // Medium: Ensure all rules are covered at least once
      return Math.max(totalRules, 30);
    } else {
      // Hard: More questions for mastery
      return Math.min(totalRules * 3, 90);
    }
  };

  const totalQuestions = getTotalQuestions();

  const getLangKey = (): 'en' | 'de' | 'uk' | 'pl' | 'sq' | 'ar' | 'it' => {
    const mapping: Record<string, 'en' | 'de' | 'uk' | 'pl' | 'sq' | 'ar' | 'it'> = {
      english: 'en',
      german: 'de',
      ukrainian: 'uk',
      polish: 'pl',
      albanian: 'sq',
      arabic: 'ar',
      italian: 'it'
    };
    return mapping[language] || 'en';
  };

  const langKey = getLangKey();

  const generateQuestion = (): GameQuestion => {
    // Collect all rules with their categories
    const allRulesWithCategories: Array<{ rule: ArticleRule; article: 'der' | 'die' | 'das' }> = [];

    articleRulesData.forEach(category => {
      category.rules.forEach(rule => {
        allRulesWithCategories.push({ rule, article: category.article });
      });
    });

    // Filter based on difficulty
    let eligibleRules = allRulesWithCategories;
    if (difficulty === 'easy') {
      // Easy: Rules with more than 20 words
      eligibleRules = allRulesWithCategories.filter(({ rule }) => rule.words.length >= 20);
    } else if (difficulty === 'hard') {
      // Hard: Include rules with exceptions or fewer examples
      eligibleRules = allRulesWithCategories.filter(({ rule }) => rule.words.length < 30);
    }

    if (eligibleRules.length === 0) eligibleRules = allRulesWithCategories;

    // Prioritize unused rules to ensure coverage
    const unusedRules = eligibleRules.filter(({ rule }) => !usedRules.has(rule.id));

    // If we have unused rules, pick from them; otherwise pick from all
    const rulesToPickFrom = unusedRules.length > 0 ? unusedRules : eligibleRules;

    // Select a random rule
    const selectedRuleData = rulesToPickFrom[Math.floor(Math.random() * rulesToPickFrom.length)];
    const { rule, article } = selectedRuleData;

    // Mark rule as used
    setUsedRules(prev => {
      const newSet = new Set(prev);
      newSet.add(rule.id);
      return newSet;
    });

    // Select a random word from the rule
    const word = rule.words[Math.floor(Math.random() * rule.words.length)];

    // Generate options
    const options: ('der' | 'die' | 'das')[] = ['der', 'die', 'das'];

    return {
      word,
      correctArticle: article,
      rule,
      options: shuffleArray(options)
    };
  };

  const shuffleArray = <T,>(array: T[]): T[] => {
    const newArray = [...array];
    for (let i = newArray.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newArray[i], newArray[j]] = [newArray[j], newArray[i]];
    }
    return newArray;
  };

  const startGame = () => {
    setIsPlaying(true);
    setQuestionCount(0);
    setUsedRules(new Set()); // Reset used rules for new game
    setStats({
      correct: 0,
      incorrect: 0,
      streak: 0,
      bestStreak: 0,
      questionsByRule: {}
    });
    setCurrentQuestion(generateQuestion());
    setSelectedAnswer(null);
    setShowResult(false);
  };

  const handleAnswer = (answer: string) => {
    if (showResult || !currentQuestion) return;

    setSelectedAnswer(answer);
    setShowResult(true);

    const isCorrect = answer === currentQuestion.correctArticle;

    // Update stats
    setStats(prev => {
      const newStreak = isCorrect ? prev.streak + 1 : 0;
      const ruleId = currentQuestion.rule.id;
      const ruleStats = prev.questionsByRule[ruleId] || { correct: 0, total: 0 };

      return {
        correct: prev.correct + (isCorrect ? 1 : 0),
        incorrect: prev.incorrect + (isCorrect ? 0 : 1),
        streak: newStreak,
        bestStreak: Math.max(prev.bestStreak, newStreak),
        questionsByRule: {
          ...prev.questionsByRule,
          [ruleId]: {
            correct: ruleStats.correct + (isCorrect ? 1 : 0),
            total: ruleStats.total + 1
          }
        }
      };
    });
  };

  const nextQuestion = () => {
    if (questionCount + 1 >= totalQuestions) {
      // Game over
      setIsPlaying(false);
      return;
    }

    setQuestionCount(prev => prev + 1);
    setCurrentQuestion(generateQuestion());
    setSelectedAnswer(null);
    setShowResult(false);
  };

  const restartGame = () => {
    startGame();
  };

  const getArticleColor = (article: string) => {
    const colors = {
      der: 'bg-blue-600 hover:bg-blue-700 border-blue-600',
      die: 'bg-pink-600 hover:bg-pink-700 border-pink-600',
      das: 'bg-green-600 hover:bg-green-700 border-green-600'
    };
    return colors[article as keyof typeof colors] || 'bg-gray-600';
  };

  const getArticleColorLight = (article: string) => {
    const colors = {
      der: 'bg-blue-100 text-blue-800 border-blue-300',
      die: 'bg-pink-100 text-pink-800 border-pink-300',
      das: 'bg-green-100 text-green-800 border-green-300'
    };
    return colors[article as keyof typeof colors] || 'bg-gray-100';
  };

  // Main Menu
  if (!isPlaying && questionCount === 0) {
    return (
      <div className="max-w-4xl mx-auto p-4">
        <div className="bg-white rounded-xl shadow-lg p-6">
          <div className="text-center mb-8">
            <div className="flex items-center justify-center gap-3 mb-4">
              <Brain size={40} className="text-purple-600" />
              <h1 className="text-3xl font-bold text-gray-800">
                {t.articlePatternGame || 'Article Pattern Game'}
              </h1>
            </div>
            <p className="text-gray-600">
              {t.articlePatternGameDesc || 'Test your knowledge of German article rules by identifying the correct article for each word!'}
            </p>
          </div>

          {/* Game Mode Selection */}
          <div className="mb-6">
            <h3 className="text-lg font-semibold text-gray-800 mb-3">
              {t.gameMode || 'Game Mode'}
            </h3>
            <div className="grid grid-cols-1 gap-3">
              <button
                onClick={() => setGameMode('article-predict')}
                className={`p-4 rounded-lg border-2 transition-all ${
                  gameMode === 'article-predict'
                    ? 'border-purple-600 bg-purple-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}
              >
                <div className="font-semibold text-gray-800">
                  {t.articlePredict || 'Article Prediction'}
                </div>
                <div className="text-sm text-gray-600 mt-1">
                  {t.articlePredictDesc || 'Choose the correct article (der/die/das) for each word'}
                </div>
              </button>
            </div>
          </div>

          {/* Difficulty Selection */}
          <div className="mb-8">
            <h3 className="text-lg font-semibold text-gray-800 mb-3">
              {t.difficulty || 'Difficulty'}
            </h3>
            <div className="grid grid-cols-3 gap-3">
              {(['easy', 'medium', 'hard'] as Difficulty[]).map((level) => (
                <button
                  key={level}
                  onClick={() => setDifficulty(level)}
                  className={`p-3 rounded-lg border-2 transition-all ${
                    difficulty === level
                      ? 'border-purple-600 bg-purple-50'
                      : 'border-gray-200 hover:border-gray-300'
                  }`}
                >
                  <div className="font-semibold text-gray-800 capitalize">
                    {level}
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* Start Button */}
          <button
            onClick={startGame}
            className="w-full py-4 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-bold text-lg transition-colors flex items-center justify-center gap-2"
          >
            <Brain size={24} />
            {t.startGame || 'Start Game'}
          </button>
        </div>
      </div>
    );
  }

  // Game Over Screen
  if (!isPlaying && questionCount > 0) {
    const accuracy = stats.correct + stats.incorrect > 0
      ? Math.round((stats.correct / (stats.correct + stats.incorrect)) * 100)
      : 0;

    return (
      <div className="max-w-4xl mx-auto p-4">
        <div className="bg-white rounded-xl shadow-lg p-6">
          <div className="text-center mb-8">
            <Trophy size={64} className="text-yellow-500 mx-auto mb-4" />
            <h2 className="text-3xl font-bold text-gray-800 mb-2">
              {t.gameOver || 'Game Over!'}
            </h2>
            <p className="text-gray-600">
              {t.finalScore || 'Here are your results:'}
            </p>
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="bg-green-50 border-2 border-green-200 rounded-lg p-4 text-center">
              <div className="text-3xl font-bold text-green-600">
                {stats.correct}
              </div>
              <div className="text-sm text-gray-600">
                {t.correct || 'Correct'}
              </div>
            </div>

            <div className="bg-red-50 border-2 border-red-200 rounded-lg p-4 text-center">
              <div className="text-3xl font-bold text-red-600">
                {stats.incorrect}
              </div>
              <div className="text-sm text-gray-600">
                {t.incorrect || 'Incorrect'}
              </div>
            </div>

            <div className="bg-purple-50 border-2 border-purple-200 rounded-lg p-4 text-center">
              <div className="text-3xl font-bold text-purple-600">
                {accuracy}%
              </div>
              <div className="text-sm text-gray-600">
                {t.accuracy || 'Accuracy'}
              </div>
            </div>

            <div className="bg-yellow-50 border-2 border-yellow-200 rounded-lg p-4 text-center">
              <div className="text-3xl font-bold text-yellow-600">
                {stats.bestStreak}
              </div>
              <div className="text-sm text-gray-600">
                {t.bestStreak || 'Best Streak'}
              </div>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={restartGame}
              className="py-3 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-semibold transition-colors flex items-center justify-center gap-2"
            >
              <RotateCcw size={20} />
              {t.playAgain || 'Play Again'}
            </button>
            <button
              onClick={() => {
                setIsPlaying(false);
                setQuestionCount(0);
              }}
              className="py-3 bg-gray-600 hover:bg-gray-700 text-white rounded-lg font-semibold transition-colors flex items-center justify-center gap-2"
            >
              <ArrowLeft size={20} />
              {t.backToMenu || 'Back to Menu'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Game Play Screen
  if (!currentQuestion) return null;

  return (
    <div className="max-w-4xl mx-auto p-4">
      {/* Progress Header */}
      <div className="bg-white rounded-xl shadow-lg p-4 mb-4">
        <div className="flex items-center justify-between mb-2">
          <div className="text-sm text-gray-600">
            {t.question || 'Question'} {questionCount + 1} / {totalQuestions}
          </div>
          <div className="flex items-center gap-4">
            <div className="text-sm">
              <span className="text-green-600 font-semibold">{stats.correct}</span>
              <span className="text-gray-400 mx-1">/</span>
              <span className="text-red-600 font-semibold">{stats.incorrect}</span>
            </div>
            <div className="text-sm text-gray-600">
              🔥 {stats.streak}
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className="bg-purple-600 h-2 rounded-full transition-all duration-300"
            style={{ width: `${((questionCount + 1) / totalQuestions) * 100}%` }}
          />
        </div>
      </div>

      {/* Question Card */}
      <div className="bg-white rounded-xl shadow-lg p-6 mb-4">
        <div className="text-center mb-6">
          <h3 className="text-lg text-gray-600 mb-4">
            {t.selectCorrectArticle || 'Select the correct article for:'}
          </h3>
          <div className="text-4xl font-bold text-gray-800 mb-2">
            {currentQuestion.word.german.split(' ')[1] || currentQuestion.word.german}
          </div>
          <div className="text-lg text-gray-600">
            ({currentQuestion.word.english})
          </div>
        </div>

        {/* Answer Options */}
        <div className="grid grid-cols-3 gap-4 mb-6">
          {currentQuestion.options.map((option) => {
            const isSelected = selectedAnswer === option;
            const isCorrect = option === currentQuestion.correctArticle;
            const showCorrectness = showResult;

            let buttonClass = `py-4 px-6 rounded-lg font-bold text-white text-xl transition-all border-2 `;

            if (!showCorrectness) {
              buttonClass += isSelected
                ? `${getArticleColor(option)} transform scale-105`
                : `${getArticleColor(option)} opacity-80 hover:opacity-100`;
            } else {
              if (isSelected && isCorrect) {
                buttonClass += 'bg-green-600 border-green-600 transform scale-105';
              } else if (isSelected && !isCorrect) {
                buttonClass += 'bg-red-600 border-red-600 transform scale-95';
              } else if (isCorrect) {
                buttonClass += 'bg-green-600 border-green-600 transform scale-105';
              } else {
                buttonClass += `${getArticleColor(option)} opacity-40`;
              }
            }

            return (
              <button
                key={option}
                onClick={() => handleAnswer(option)}
                disabled={showResult}
                className={buttonClass}
              >
                {option}
              </button>
            );
          })}
        </div>

        {/* Result Feedback */}
        {showResult && (
          <div className={`p-4 rounded-lg border-2 mb-4 ${
            selectedAnswer === currentQuestion.correctArticle
              ? 'bg-green-50 border-green-300'
              : 'bg-red-50 border-red-300'
          }`}>
            <div className="flex items-center gap-3 mb-3">
              {selectedAnswer === currentQuestion.correctArticle ? (
                <>
                  <CheckCircle2 size={24} className="text-green-600" />
                  <span className="font-semibold text-green-800">
                    {t.correct || 'Correct!'}
                  </span>
                </>
              ) : (
                <>
                  <XCircle size={24} className="text-red-600" />
                  <span className="font-semibold text-red-800">
                    {t.incorrect || 'Incorrect'}
                  </span>
                </>
              )}
            </div>

            {/* Rule Explanation */}
            <div className="bg-white rounded p-3 border border-gray-200">
              <div className="text-sm font-semibold text-gray-800 mb-1">
                {currentQuestion.rule.ruleTitle[langKey]}
              </div>
              <div className="text-sm text-gray-600">
                {currentQuestion.rule.ruleDescription[langKey]}
              </div>
              <div className="mt-2 flex flex-wrap gap-2">
                {currentQuestion.rule.examples.map((example, idx) => (
                  <span
                    key={idx}
                    className={`px-2 py-1 text-xs font-semibold rounded ${
                      getArticleColorLight(currentQuestion.correctArticle)
                    }`}
                  >
                    {example}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Next Button */}
        {showResult && (
          <button
            onClick={nextQuestion}
            className="w-full py-3 bg-purple-600 hover:bg-purple-700 text-white rounded-lg font-semibold transition-colors"
          >
            {questionCount + 1 >= totalQuestions
              ? t.seeResults || 'See Results'
              : t.nextQuestion || 'Next Question'}
          </button>
        )}
      </div>
    </div>
  );
};
