// src/components/studyguide/MarkdownRenderer.tsx
import React, { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Loader2 } from 'lucide-react';

interface MarkdownRendererProps {
    getContent: () => Promise<string>;
}

export const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ getContent }) => {
    const [content, setContent] = useState<string>('');
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const loadMarkdown = async () => {
            setLoading(true);
            setError(null);

            try {
                const text = await getContent();
                setContent(text);
            } catch (err) {
                console.error('Error loading markdown:', err);
                setError('Failed to load study guide. Please try again.');
            } finally {
                setLoading(false);
            }
        };

        loadMarkdown();
    }, [getContent]);

    if (loading) {
        return (
            <div className="flex items-center justify-center p-12">
                <Loader2 className="animate-spin text-indigo-600" size={48} />
                <span className="ml-4 text-lg text-gray-600">Loading study guide...</span>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
                <p className="text-red-600 font-semibold">{error}</p>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-xl shadow-lg p-8 prose prose-lg max-w-none
                        prose-headings:text-gray-800
                        prose-h1:text-3xl prose-h1:font-bold prose-h1:mb-4 prose-h1:text-indigo-600
                        prose-h2:text-2xl prose-h2:font-bold prose-h2:mt-8 prose-h2:mb-4 prose-h2:text-indigo-600
                        prose-h3:text-xl prose-h3:font-semibold prose-h3:mt-6 prose-h3:mb-3 prose-h3:text-gray-700
                        prose-p:text-gray-700 prose-p:leading-relaxed
                        prose-a:text-indigo-600 prose-a:no-underline hover:prose-a:underline
                        prose-strong:text-gray-900 prose-strong:font-bold
                        prose-code:text-indigo-600 prose-code:bg-indigo-50 prose-code:px-1 prose-code:rounded
                        prose-pre:bg-gray-50 prose-pre:border prose-pre:border-gray-200
                        prose-blockquote:border-l-4 prose-blockquote:border-indigo-400 prose-blockquote:bg-indigo-50 prose-blockquote:italic
                        prose-ul:list-disc prose-ul:ml-6
                        prose-ol:list-decimal prose-ol:ml-6
                        prose-li:text-gray-700
                        prose-table:border-collapse
                        prose-th:bg-indigo-100 prose-th:border prose-th:border-gray-300 prose-th:p-2 prose-th:font-bold
                        prose-td:border prose-td:border-gray-300 prose-td:p-2
                        prose-img:rounded-lg prose-img:shadow-md"
        >
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
                {content}
            </ReactMarkdown>
        </div>
    );
};
