import React, { useState, useMemo, useCallback } from 'react';
import { BookOpen, Brain, ChevronDown, ChevronUp } from 'lucide-react';
import { useAppContext } from '../../hooks/useAppContext';
import { languages } from '../../data/languages';
import { examDecks, TOTAL_WORDS, WORDS_PER_DECK, EXAM_SECTIONS } from '../../data/examPrep';
import { DailyDeck } from './DailyDeck';
import { DailyQuiz } from './DailyQuiz';

type View = 'deck' | 'quiz';

export const ExamPrepMode: React.FC = () => {
  const { language } = useAppContext();
  const t = languages[language];

  const [view, setView] = useState<View>('deck');
  const [selectedSections, setSelectedSections] = useState<number[]>([1]);
  const [selectorOpen, setSelectorOpen] = useState(true);

  const cards = useMemo(
    () => selectedSections.flatMap(s => examDecks[s] || []),
    [selectedSections]
  );

  const toggleSection = useCallback((section: number) => {
    setSelectedSections(prev =>
      prev.includes(section)
        ? prev.length > 1 ? prev.filter(s => s !== section) : prev
        : [...prev, section].sort((a, b) => a - b)
    );
  }, []);

  const selectAll = useCallback(() => {
    setSelectedSections([...EXAM_SECTIONS]);
  }, []);

  const handleDeckComplete = useCallback(() => {
    setView('quiz');
  }, []);

  const handleQuizComplete = useCallback(() => {
    // no-op, quiz shows its own results
  }, []);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-800">{t.examPrep}</h2>
        <p className="text-gray-500 mt-1">{t.examPrepDesc}</p>
        <div className="flex justify-center gap-4 mt-3 text-sm">
          <span className="bg-rose-50 text-rose-700 px-3 py-1 rounded-full font-medium">
            {TOTAL_WORDS} words total
          </span>
          <span className="bg-orange-50 text-orange-700 px-3 py-1 rounded-full font-medium">
            {cards.length} {t.currentCard.toLowerCase()}s selected
          </span>
        </div>
      </div>

      {/* View switcher */}
      <div className="flex justify-center">
        <div className="flex p-1 bg-gray-200 rounded-xl gap-1">
          <button
            onClick={() => setView('deck')}
            className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-colors
              ${view === 'deck' ? 'bg-white text-rose-600 shadow-md' : 'text-gray-600 hover:text-gray-800'}`}
          >
            <BookOpen size={18} /> {t.currentCard}s
          </button>
          <button
            onClick={() => setView('quiz')}
            className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold rounded-lg transition-colors
              ${view === 'quiz' ? 'bg-white text-rose-600 shadow-md' : 'text-gray-600 hover:text-gray-800'}`}
          >
            <Brain size={18} /> {t.dailyQuiz}
          </button>
        </div>
      </div>

      {/* Section selector */}
      <div className="max-w-2xl mx-auto">
        <button
          onClick={() => setSelectorOpen(!selectorOpen)}
          className="flex items-center justify-between w-full px-4 py-3 bg-white rounded-xl shadow text-sm font-semibold text-gray-700 hover:bg-gray-50 transition-colors"
        >
          <span>{t.selectSections} ({selectedSections.length} / {EXAM_SECTIONS.length})</span>
          {selectorOpen ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
        </button>

        {selectorOpen && (
          <div className="mt-2 bg-white rounded-xl shadow-lg p-4">
            <div className="flex flex-wrap gap-2 mb-3">
              {EXAM_SECTIONS.map(section => (
                <button
                  key={section}
                  onClick={() => toggleSection(section)}
                  className={`min-w-[3rem] px-3 py-1.5 rounded-lg text-sm font-medium transition-all
                    ${selectedSections.includes(section)
                      ? 'bg-rose-500 text-white shadow-sm'
                      : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                    }`}
                >
                  {section}
                </button>
              ))}
            </div>
            <button
              onClick={selectAll}
              className="w-full px-4 py-2 bg-rose-500 text-white rounded-lg hover:bg-rose-600 transition-colors text-sm font-semibold"
            >
              {t.allSections}
            </button>
          </div>
        )}
      </div>

      {/* Content */}
      {cards.length > 0 && view === 'deck' && (
        <DailyDeck
          cards={cards}
          language={language}
          t={t}
          onComplete={handleDeckComplete}
        />
      )}

      {cards.length > 0 && view === 'quiz' && (
        <DailyQuiz
          cards={cards}
          language={language}
          t={t}
          onComplete={handleQuizComplete}
        />
      )}
    </div>
  );
};
