import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Shuffle, RotateCcw, Volume2, Copy, Check } from 'lucide-react';
import { ExamCard, LanguageKey } from '../../types';
import { LanguageStrings } from '../../types';
import { highlightWord } from './utils';

interface DailyDeckProps {
  cards: ExamCard[];
  language: LanguageKey;
  t: LanguageStrings;
  onComplete: () => void;
}

export const DailyDeck: React.FC<DailyDeckProps> = ({ cards, language, t, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [deck, setDeck] = useState<ExamCard[]>(cards);
  const [viewedCards, setViewedCards] = useState<Set<number>>(new Set());
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    audioRef.current = new Audio();
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    setDeck(cards);
    setCurrentIndex(0);
    setIsFlipped(false);
    setViewedCards(new Set());
  }, [cards]);

  const current = deck[currentIndex];
  const progress = viewedCards.size;
  const total = deck.length;
  const allViewed = progress >= total;

  const markViewed = useCallback((idx: number) => {
    setViewedCards(prev => new Set(prev).add(idx));
  }, []);

  const nextCard = useCallback(() => {
    markViewed(currentIndex);
    setIsFlipped(false);
    if (currentIndex < deck.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      markViewed(currentIndex);
    }
  }, [currentIndex, deck.length, markViewed]);

  const prevCard = useCallback(() => {
    setIsFlipped(false);
    setCurrentIndex(prev => Math.max(0, prev - 1));
  }, []);

  const shuffle = useCallback(() => {
    const shuffled = [...deck].sort(() => Math.random() - 0.5);
    setDeck(shuffled);
    setCurrentIndex(0);
    setIsFlipped(false);
  }, [deck]);

  const reset = useCallback(() => {
    setDeck(cards);
    setCurrentIndex(0);
    setIsFlipped(false);
    setViewedCards(new Set());
  }, [cards]);

  const playAudio = useCallback(() => {
    if (!audioRef.current || !current?.audioSrc) return;
    const src = current.audioSrc.startsWith('http')
      ? current.audioSrc
      : `${process.env.PUBLIC_URL}${current.audioSrc}`;
    audioRef.current.src = src;
    audioRef.current.play().catch(() => {});
  }, [current]);

  const translation = useMemo(() => {
    if (!current) return '';
    return current.translations.word[language] || current.german;
  }, [current, language]);

  const sentenceTranslations = useMemo(() => {
    if (!current) return [];
    return current.translations.sentences[language] || [];
  }, [current, language]);

  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const copySentence = useCallback((e: React.MouseEvent, sentence: string, index: number) => {
    e.stopPropagation();
    navigator.clipboard.writeText(sentence).then(() => {
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 1500);
    }).catch(() => {});
  }, []);

  if (!current) return null;

  return (
    <div className="max-w-2xl mx-auto">
      {/* Progress bar */}
      <div className="mb-4">
        <div className="flex justify-between text-sm text-gray-600 mb-1">
          <span>{t.currentCard} {currentIndex + 1} {t.of} {total}</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className="bg-rose-500 h-2 rounded-full transition-all"
            style={{ width: `${((currentIndex + 1) / total) * 100}%` }}
          />
        </div>
      </div>

      {/* Card */}
      <div
        onClick={() => setIsFlipped(!isFlipped)}
        className="relative min-h-[320px] bg-white rounded-2xl shadow-lg cursor-pointer p-8 border-2 border-rose-100 hover:shadow-xl transition-shadow"
      >
        {/* Audio button — top-left corner */}
        {current.audioSrc && (
          <button
            onClick={(e) => { e.stopPropagation(); playAudio(); }}
            className="absolute top-4 left-4 p-2 rounded-full text-gray-500 hover:bg-rose-100 hover:text-rose-600 transition-colors z-10"
            title={t.playAudio}
          >
            <Volume2 size={24} />
          </button>
        )}

        {!isFlipped ? (
          /* Front: German word + translation */
          <div className="flex flex-col items-center justify-center h-full text-center space-y-3">
            <p className="text-4xl font-bold text-gray-900">{current.german}</p>
            {current.form && (
              <p className="text-lg italic text-gray-500">{current.form}</p>
            )}
            <p className="text-xl text-rose-600 font-semibold">{translation}</p>
            <p className="text-sm text-gray-400 mt-4">{t.clickToFlip}</p>
          </div>
        ) : (
          /* Back: Sentences with highlights + translations */
          <div className="space-y-4">
            <div className="text-center">
              <p className="text-2xl font-bold text-gray-900">{current.german}</p>
              <p className="text-lg text-rose-600 font-semibold mt-1">{translation}</p>
            </div>
            <hr className="border-gray-200" />
            <div className="space-y-3">
              {current.sentences.map((sent, i) => {
                const highlighted = highlightWord(sent, current.german);
                return (
                  <div key={i} className="space-y-1">
                    <div className="flex items-start gap-2">
                      <p className="text-gray-800 flex-1">
                        {highlighted.split(/\*\*(.*?)\*\*/).map((part, j) =>
                          j % 2 === 1 ? (
                            <span key={j} className="font-bold text-rose-600 underline">{part}</span>
                          ) : (
                            <span key={j}>{part}</span>
                          )
                        )}
                      </p>
                      <button
                        onClick={(e) => copySentence(e, sent, i)}
                        className="flex-shrink-0 p-1 rounded text-gray-400 hover:text-rose-600 hover:bg-rose-50 transition-colors"
                        title="Copy sentence"
                      >
                        {copiedIndex === i ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
                      </button>
                    </div>
                    {sentenceTranslations[i] && (
                      <p className="text-sm text-gray-500 italic">{sentenceTranslations[i]}</p>
                    )}
                  </div>
                );
              })}
            </div>
            <p className="text-sm text-gray-400 text-center mt-4">{t.clickToFlipBack}</p>
          </div>
        )}
      </div>

      {/* Controls */}
      <div className="flex items-center justify-center gap-3 mt-6">
        <button
          onClick={prevCard}
          disabled={currentIndex === 0}
          className="p-2 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 disabled:opacity-30 transition-colors"
        >
          <ChevronLeft size={24} />
        </button>
        <button
          onClick={shuffle}
          className="p-2 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 transition-colors"
          title={t.shuffle}
        >
          <Shuffle size={20} />
        </button>
        <button
          onClick={reset}
          className="p-2 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 transition-colors"
          title={t.reset}
        >
          <RotateCcw size={20} />
        </button>
        <button
          onClick={nextCard}
          disabled={currentIndex >= deck.length - 1}
          className="p-2 rounded-lg bg-gray-100 text-gray-600 hover:bg-gray-200 disabled:opacity-30 transition-colors"
        >
          <ChevronRight size={24} />
        </button>
      </div>

      {/* Complete button */}
      {allViewed && (
        <div className="mt-6 text-center">
          <button
            onClick={onComplete}
            className="px-6 py-3 bg-rose-600 text-white font-semibold rounded-xl hover:bg-rose-700 transition-colors shadow-md"
          >
            {t.startQuiz}
          </button>
        </div>
      )}
    </div>
  );
};
