// src/components/studyguide/ModuleSelector.tsx
import React from 'react';
import { BookOpen } from 'lucide-react';
import { StudyGuideModule } from '../../data/levels/a2.2/studyguides';

interface ModuleSelectorProps {
    modules: StudyGuideModule[];
    selectedModule: StudyGuideModule | null;
    onSelectModule: (module: StudyGuideModule) => void;
}

export const ModuleSelector: React.FC<ModuleSelectorProps> = ({
    modules,
    selectedModule,
    onSelectModule
}) => {
    return (
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
            <h2 className="text-2xl font-bold mb-4 text-gray-800 flex items-center gap-2">
                <BookOpen className="text-indigo-600" size={28} />
                Select a Module
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {modules.map((module) => (
                    <button
                        key={module.id}
                        onClick={() => onSelectModule(module)}
                        className={`p-4 rounded-lg border-2 transition-all text-left ${
                            selectedModule?.id === module.id
                                ? 'border-indigo-600 bg-indigo-50 shadow-md'
                                : 'border-gray-200 hover:border-indigo-400 hover:bg-gray-50'
                        }`}
                    >
                        <div className="font-bold text-lg text-indigo-600 mb-2">
                            Module {module.id}
                        </div>
                        <div className="font-semibold text-gray-800 mb-1">
                            {module.title.split(': ')[1]}
                        </div>
                        <div className="text-sm text-gray-600">
                            {module.description}
                        </div>
                    </button>
                ))}
            </div>
        </div>
    );
};
