import React, { useState, useMemo, useCallback } from 'react';
import { CheckCircle, XCircle, ArrowRight } from 'lucide-react';
import { ExamCard, LanguageKey, LanguageStrings } from '../../types';

interface DailyQuizProps {
  cards: ExamCard[];
  language: LanguageKey;
  t: LanguageStrings;
  onComplete: (score: number) => void;
}

type QuizQuestion = {
  type: 'multiple-choice' | 'type-word';
  german: string;
  correctAnswer: string;
  options?: string[];
  sentence?: string;
};

function generateQuestions(cards: ExamCard[], language: LanguageKey): QuizQuestion[] {
  const questions: QuizQuestion[] = [];
  // Pick ~10 random cards
  const shuffled = [...cards].sort(() => Math.random() - 0.5);
  const selected = shuffled.slice(0, Math.min(10, cards.length));

  selected.forEach((card, i) => {
    const translation = card.translations.word[language] || card.german;

    if (i % 2 === 0) {
      // Multiple choice: "What does X mean?"
      const wrongOptions = shuffled
        .filter(c => c.german !== card.german)
        .sort(() => Math.random() - 0.5)
        .slice(0, 3)
        .map(c => c.translations.word[language] || c.german);

      const allOptions = [translation, ...wrongOptions].sort(() => Math.random() - 0.5);

      questions.push({
        type: 'multiple-choice',
        german: card.german,
        correctAnswer: translation,
        options: allOptions,
        sentence: card.sentences[0],
      });
    } else {
      // Type the German word given translation
      questions.push({
        type: 'type-word',
        german: card.german,
        correctAnswer: card.german.replace(/^(der|die|das)\s+/, ''),
        sentence: card.sentences[0],
      });
    }
  });

  return questions;
}

export const DailyQuiz: React.FC<DailyQuizProps> = ({ cards, language, t, onComplete }) => {
  const questions = useMemo(() => generateQuestions(cards, language), [cards, language]);
  const [currentQ, setCurrentQ] = useState(0);
  const [answer, setAnswer] = useState('');
  const [selectedOption, setSelectedOption] = useState<string | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);
  const [finished, setFinished] = useState(false);

  const q = questions[currentQ];

  const checkAnswer = useCallback(() => {
    if (!q) return;
    let correct = false;

    if (q.type === 'multiple-choice') {
      correct = selectedOption === q.correctAnswer;
    } else {
      // Normalize comparison - case insensitive, trim
      const normalized = answer.trim().toLowerCase();
      const expected = q.correctAnswer.toLowerCase();
      correct = normalized === expected;
    }

    setIsCorrect(correct);
    setIsAnswered(true);
    if (correct) setCorrectCount(prev => prev + 1);
  }, [q, selectedOption, answer]);

  const nextQuestion = useCallback(() => {
    if (currentQ >= questions.length - 1) {
      const score = Math.round(((correctCount + (isCorrect ? 0 : 0)) / questions.length) * 100);
      setFinished(true);
      onComplete(score);
      return;
    }
    setCurrentQ(prev => prev + 1);
    setAnswer('');
    setSelectedOption(null);
    setIsAnswered(false);
    setIsCorrect(false);
  }, [currentQ, questions.length, correctCount, isCorrect, onComplete]);

  if (finished) {
    const score = Math.round((correctCount / questions.length) * 100);
    return (
      <div className="max-w-lg mx-auto text-center space-y-6 py-8">
        <div className="text-6xl">{score >= 70 ? '🎉' : score >= 40 ? '💪' : '📚'}</div>
        <h2 className="text-2xl font-bold text-gray-800">{t.quizScore}</h2>
        <p className="text-5xl font-extrabold text-rose-600">{score}%</p>
        <p className="text-gray-500">
          {correctCount} / {questions.length} {t.correct.toLowerCase()}
        </p>
      </div>
    );
  }

  if (!q) return null;

  return (
    <div className="max-w-lg mx-auto space-y-6">
      {/* Progress */}
      <div className="flex justify-between text-sm text-gray-500">
        <span>{t.dailyQuiz}</span>
        <span>{t.question} {currentQ + 1} / {questions.length}</span>
      </div>
      <div className="w-full bg-gray-200 rounded-full h-2">
        <div
          className="bg-rose-500 h-2 rounded-full transition-all"
          style={{ width: `${((currentQ + 1) / questions.length) * 100}%` }}
        />
      </div>

      {/* Question card */}
      <div className="bg-white rounded-2xl shadow-lg p-6 border border-rose-100">
        {q.type === 'multiple-choice' ? (
          <div className="space-y-4">
            <p className="text-lg font-semibold text-gray-700">
              What does <span className="text-rose-600 font-bold text-xl">"{q.german}"</span> mean?
            </p>
            {q.sentence && (
              <p className="text-sm text-gray-500 italic bg-gray-50 p-3 rounded-lg">
                {q.sentence}
              </p>
            )}
            <div className="grid gap-2">
              {q.options?.map((opt, i) => {
                const isSelected = selectedOption === opt;
                const showResult = isAnswered;
                const isRight = opt === q.correctAnswer;
                return (
                  <button
                    key={i}
                    onClick={() => !isAnswered && setSelectedOption(opt)}
                    disabled={isAnswered}
                    className={`
                      w-full text-left px-4 py-3 rounded-xl border-2 font-medium transition-all
                      ${showResult && isRight
                        ? 'border-green-500 bg-green-50 text-green-700'
                        : showResult && isSelected && !isRight
                        ? 'border-red-500 bg-red-50 text-red-700'
                        : isSelected
                        ? 'border-rose-500 bg-rose-50 text-rose-700'
                        : 'border-gray-200 hover:border-rose-300 text-gray-700'
                      }
                    `}
                  >
                    <div className="flex items-center justify-between">
                      <span>{opt || `Option ${i + 1}`}</span>
                      {showResult && isRight && <CheckCircle size={20} className="text-green-500" />}
                      {showResult && isSelected && !isRight && <XCircle size={20} className="text-red-500" />}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <p className="text-lg font-semibold text-gray-700">
              Type the German word for:
            </p>
            <p className="text-2xl font-bold text-rose-600 text-center py-2">{q.german}</p>
            {q.sentence && (
              <p className="text-sm text-gray-500 italic bg-gray-50 p-3 rounded-lg">
                {q.sentence}
              </p>
            )}
            <input
              type="text"
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !isAnswered && checkAnswer()}
              disabled={isAnswered}
              className={`
                w-full px-4 py-3 rounded-xl border-2 text-lg font-medium outline-none transition-all
                ${isAnswered
                  ? isCorrect
                    ? 'border-green-500 bg-green-50'
                    : 'border-red-500 bg-red-50'
                  : 'border-gray-200 focus:border-rose-400'
                }
              `}
              placeholder="Type your answer..."
              autoFocus
            />
            {isAnswered && !isCorrect && (
              <p className="text-sm text-gray-600">
                Correct: <span className="font-bold text-green-600">{q.correctAnswer}</span>
              </p>
            )}
          </div>
        )}
      </div>

      {/* Action button */}
      <div className="flex justify-center">
        {!isAnswered ? (
          <button
            onClick={checkAnswer}
            disabled={q.type === 'multiple-choice' ? !selectedOption : !answer.trim()}
            className="px-8 py-3 bg-rose-600 text-white font-semibold rounded-xl hover:bg-rose-700 disabled:opacity-40 transition-all shadow-md"
          >
            {t.checkAnswer}
          </button>
        ) : (
          <button
            onClick={nextQuestion}
            className="flex items-center gap-2 px-8 py-3 bg-rose-600 text-white font-semibold rounded-xl hover:bg-rose-700 transition-all shadow-md"
          >
            {currentQ < questions.length - 1 ? t.nextExercise : t.seeResults}
            <ArrowRight size={18} />
          </button>
        )}
      </div>
    </div>
  );
};
