// src/components/studyguide/StudyGuideMode.tsx
import React, { useState } from 'react';
import { ArrowLeft, BookOpenCheck } from 'lucide-react';
import { studyGuides, StudyGuideModule } from '../../data/levels/a2.2/studyguides';
import { ModuleSelector } from './ModuleSelector';
import { MarkdownRenderer } from './MarkdownRenderer';
import { LanguageStrings } from '../../types';

interface StudyGuideModeProps {
    t: LanguageStrings;
}

export const StudyGuideMode: React.FC<StudyGuideModeProps> = ({ t }) => {
    const [selectedModule, setSelectedModule] = useState<StudyGuideModule | null>(null);

    const handleSelectModule = (module: StudyGuideModule) => {
        setSelectedModule(module);
        // Scroll to top when a new module is selected
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleBackToList = () => {
        setSelectedModule(null);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    return (
        <div className="max-w-7xl mx-auto">
            {!selectedModule ? (
                <>
                    {/* Welcome Section */}
                    <div className="bg-gradient-to-r from-indigo-600 to-purple-600 rounded-xl shadow-lg p-8 mb-6 text-white">
                        <div className="flex items-center gap-3 mb-4">
                            <BookOpenCheck size={40} />
                            <h1 className="text-3xl font-bold">{t.studyGuide || 'Study Guides'}</h1>
                        </div>
                        <p className="text-lg opacity-90">
                            {t.studyGuideDescription ||
                                'Comprehensive self-study guides for Modules 7-14 (A2.2 level). Each guide includes detailed explanations, vocabulary lists, grammar breakdowns, practice exercises, and cultural insights.'}
                        </p>
                    </div>

                    {/* Module Selection */}
                    <ModuleSelector
                        modules={studyGuides}
                        selectedModule={selectedModule}
                        onSelectModule={handleSelectModule}
                    />

                    {/* Information Box */}
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-6 mt-6">
                        <h3 className="font-bold text-lg text-blue-800 mb-2">
                            📚 How to Use These Guides
                        </h3>
                        <ul className="list-disc ml-6 text-blue-900 space-y-1">
                            <li>Each module corresponds to a chapter in your textbook (Kursbuch)</li>
                            <li>Read the study guide BEFORE working on Arbeitsbuch exercises</li>
                            <li>Use the vocabulary lists to create flashcards</li>
                            <li>Complete the practice exercises and check your answers</li>
                            <li>Test yourself with the self-check questions at the end</li>
                        </ul>
                    </div>
                </>
            ) : (
                <>
                    {/* Back Button and Module Title */}
                    <div className="mb-6">
                        <button
                            onClick={handleBackToList}
                            className="flex items-center gap-2 px-4 py-2 bg-white border-2 border-gray-300
                                     rounded-lg hover:bg-gray-50 hover:border-indigo-400 transition-colors
                                     font-semibold text-gray-700 mb-4"
                        >
                            <ArrowLeft size={20} />
                            Back to Module List
                        </button>

                        <div className="bg-gradient-to-r from-indigo-600 to-purple-600 rounded-xl shadow-lg p-6 text-white">
                            <div className="text-sm font-semibold opacity-90 mb-1">
                                MODULE {selectedModule.id}
                            </div>
                            <h1 className="text-3xl font-bold mb-2">
                                {selectedModule.title.split(': ')[1]}
                            </h1>
                            <p className="text-lg opacity-90">
                                {selectedModule.description}
                            </p>
                        </div>
                    </div>

                    {/* Markdown Content */}
                    <MarkdownRenderer getContent={selectedModule.getContent} />

                    {/* Back to Top Button */}
                    <div className="mt-6 flex justify-center">
                        <button
                            onClick={handleBackToList}
                            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white
                                     rounded-lg hover:bg-indigo-700 transition-colors
                                     font-semibold shadow-md"
                        >
                            <ArrowLeft size={20} />
                            Back to Module List
                        </button>
                    </div>
                </>
            )}
        </div>
    );
};
